export const isUnique = <T>(item: T, pos: number, arr: T[]) =>
  arr.indexOf(item) == pos;

/** Generate an array of numbers, from start till end, with optional step size. */
export const generateNumbers = (
  start: number,
  end: number,
  step: number = 1,
): number[] => {
  if (start > end) {
    throw new Error(
      'Start number must be less than or equal to the end number.',
    );
  }

  if (step <= 0) {
    throw new Error('Step size must be a positive number.');
  }

  const length = Math.floor((end - start) / step) + 1;
  return Array.from({ length }, (_, index) => start + index * step);
};

export const getRandomValue = <T>(array: T[]): T | undefined => {
  if (array.length === 0) {
    return undefined;
  }

  const randomIndex = Math.floor(Math.random() * array.length);
  return array[randomIndex];
};

/**
 * Deep copy function for TypeScript.
 * @param T Generic type of target/copied value.
 * @param target Target value to be copied.
 * @see Source project, ts-deepcopy https://github.com/ykdr2017/ts-deepcopy
 * @see Code pen https://codepen.io/erikvullings/pen/ejyBYg
 */
export const deepCopy = <T>(target: T): T => {
  if (target === null) {
    return target;
  }
  if (target instanceof Date) {
    return new Date(target.getTime()) as any;
  }
  if (target instanceof Array) {
    const cp = [] as any[];
    (target as any[]).forEach((v) => {
      cp.push(v);
    });
    return cp.map((n: any) => deepCopy<any>(n)) as any;
  }
  if (typeof target === 'object') {
    const cp = { ...(target as { [key: string]: any }) } as {
      [key: string]: any;
    };
    Object.keys(cp).forEach((k) => {
      cp[k] = deepCopy<any>(cp[k]);
    });
    return cp as T;
  }
  return target;
};

export const convertFromOld = (old: OldDataModel): DataModel => {
  return Object.keys(old).reduce(
    (acc, cur) => {
      if (cur === 'scenarios') {
        // Parse scenarios
        const scenario = old[cur].current;
        acc.scenario.id = scenario.id;
        acc.scenario.label = scenario.name;
        acc.scenario.desc = scenario.desc;
        acc.scenario.hideInconsistentValues = true;
        acc.scenario.inconsistencies = scenario.inconsistencies.reduce(
          (acc, cur) => {
            const {
              ids: [from, to],
              type,
            } = cur;
            if (!acc[from]) acc[from] = {};
            if (!acc[to]) acc[to] = {};
            const value = type === 'totally' ? true : false;
            acc[from][to] = value;
            acc[to][from] = value;
            return acc;
          },
          {} as Inconsistencies,
        );
        acc.scenario.narratives = scenario.narratives.map(
          ({ id, name, components, narrative, included }) => ({
            id,
            label: name,
            components: Object.keys(components).reduce(
              (acc, key) => {
                acc[key] = [components[key]];
                return acc;
              },
              {} as { [key: ID]: ID[] },
            ),
            desc: narrative,
            included,
            saved: true,
            personaEffects: {},
          }),
        );
        acc.scenario.categories = Object.keys(scenario.categories).map(
          (key) => ({
            id: key,
            label: key,
            componentIds: scenario.categories[key],
          }),
        );
      } else {
        // Parse components
        if (!acc.scenario.components) acc.scenario.components = [];
        const componentValues = old[cur].list;
        const contexts = componentValues.reduce((acc, cur) => {
          if (cur.context && cur.context.type) {
            if (cur.context.type === 'LOCATION' && acc.indexOf('location') <= 0)
              acc.push('location');
            else if (
              cur.context.type === 'LOCATIONTYPE' &&
              acc.indexOf('locationType') <= 0
            )
              acc.push('locationType');
          }
          return acc;
        }, [] as ContextType[]);
        acc.scenario.components.push({
          id: cur,
          label: t('COMP', cur.toUpperCase() as any),
          contexts,
          values: componentValues.map(({ name, id, desc, context }) => {
            const newContext = context
              ? context.type === 'LOCATION'
                ? 'location'
                : context.type === 'LOCATIONTYPE'
                  ? 'locationType'
                  : 'none'
              : undefined;
            const locationType =
              context && context.type === 'LOCATION'
                ? context.data.NAME
                  ? 'name'
                  : context.data.COORDINATES
                    ? 'coords'
                    : undefined
                : undefined;
            const [lat, lon] =
              locationType === 'coords' && context!.data.COORDINATES
                ? context!.data.COORDINATES.split(/,/).map((n) => +n)
                : [undefined, undefined];
            const locationTypeType =
              context && context.type === 'LOCATIONTYPE'
                ? OsmTypeList.indexOf(Object.keys(context.data).shift()) >= 0
                  ? 'list'
                  : 'keyValue'
                : undefined;
            const osmTypeId =
              locationTypeType === 'list'
                ? Object.keys(context!.data).shift()
                : undefined;
            const keyValue =
              locationTypeType === 'keyValue'
                ? Object.entries(context!.data).shift()
                : undefined;
            const [key, value] = keyValue || [undefined, undefined];
            return {
              id,
              label: name,
              desc,
              context: newContext,
              location:
                context && context.type === 'LOCATION'
                  ? context.data.NAME
                  : undefined,
              locationType,
              locationTypeType,
              lat,
              lon,
              osmTypeId,
              key,
              value,
            };
          }),
        });
        acc.scenario.thresholdColors = thresholdColors;
        if (acc.scenario.categories) {
          let order = 1;
          const compIds = acc.scenario.categories
            .filter((c) => c.componentIds)
            .reduce(
              (acc, cur) => {
                cur.componentIds?.forEach((c) => (acc[c] = order++));
                return acc;
              },
              {} as { [key: ID]: number },
            );
          acc.scenario.components = acc.scenario.components.map((c) => ({
            ...c,
            order: compIds[c.id],
          }));
          acc.scenario.components.sort((a, b) =>
            a.order! > b.order! ? 1 : -1,
          );
        }
      }
      return acc;
    },
    {
      scenario: {} as Scenario,
      version: 1,
      lastUpdate: Date.now(),
      scenarios: [],
    } as DataModel,
  );
};

export const modelToSaveName = (
  model: DataModel,
  narrativeName?: string,
  isCollection = true,
) => {
  let name = isCollection
    ? 'spark_collection'
    : (model.scenario?.label || 'spark') + '_model';
  if (narrativeName) {
    name += `_${narrativeName}`;
  }
  return `${name?.toString().replace(/\s/g, '_')}_v${padLeft(
    model.version || 1,
    3,
  )}_${formatDate()}`.toLowerCase();
};

/** Diagnostic result for morphological box dead-end */
export type GenerationDiagnostic = {
  /** Components that have severely constrained values (< 2 available) */
  blockedComponents: Array<{
    componentId: ID;
    componentLabel: string;
    totalValues: number;
    availableValues: number;
    blockedValueIds: ID[];
  }>;
  /** Total inconsistency constraints */
  totalConstraints: number;
};

/**
 * Diagnose why morphological box generation is failing.
 * Analyzes which components have all values blocked by inconsistency constraints.
 */
export const diagnoseGeneration = (
  scenario: Scenario,
): GenerationDiagnostic => {
  const { categories, components, inconsistencies } = scenario;

  // Count how many values are blocked for each component
  const blockedMap = new Map<ID, ID[]>(); // componentId -> blocked value ids

  for (const category of categories) {
    const catComps = components.filter(
      (c) => category.componentIds && category.componentIds.includes(c.id),
    );
    for (const comp of catComps) {
      if (!comp.values) continue;
      const blocked = comp.values
        .filter(
          (v) =>
            inconsistencies[v.id] &&
            Object.keys(inconsistencies[v.id]).length > 0,
        )
        .map((v) => v.id);
      if (blocked.length > 0) {
        blockedMap.set(comp.id, blocked);
      }
    }
  }

  const blockedComponents = Array.from(blockedMap.entries())
    .map(([compId, blockedIds]) => {
      const comp = components.find((c) => c.id === compId);
      return {
        componentId: compId,
        componentLabel: comp?.label || compId,
        totalValues: comp?.values?.length || 0,
        availableValues: (comp?.values?.length || 0) - blockedIds.length,
        blockedValueIds: blockedIds,
      };
    })
    .filter((c) => c.availableValues < 2)
    .sort((a, b) => a.availableValues - b.availableValues);

  const totalConstraints = Object.values(inconsistencies).reduce(
    (sum, row) => sum + Object.values(row).filter(Boolean).length,
    0,
  );

  return { blockedComponents, totalConstraints };
};

const getInconsistency = (
  inconsistencies: Inconsistencies,
  from: ID,
  to: ID,
) => {
  const fromValue = inconsistencies[from]?.[to];
  if (typeof fromValue !== 'undefined') return fromValue;
  return inconsistencies[to]?.[from];
};

const countConstraints = (inconsistencies: Inconsistencies, id: ID) =>
  Object.values(inconsistencies[id] || {}).reduce(
    (count, value) => count + (value ? 2 : 1),
    0,
  );

const getScenarioComponents = (
  categories: Scenario['categories'],
  components: ScenarioComponent[],
) => {
  const seen = new Set<ID>();
  const byId = new Map(components.map((component) => [component.id, component]));
  return categories
    .flatMap((category) => category.componentIds || [])
    .map((id) => byId.get(id))
    .filter((component): component is ScenarioComponent => {
      if (!component || seen.has(component.id)) return false;
      seen.add(component.id);
      return true;
    });
};

const getSelectedValueIds = (chosen: Record<ID, ID[]>) =>
  Object.values(chosen).flatMap((ids) => ids || []);

const getPairScore = (
  inconsistencies: Inconsistencies,
  id: ID,
  selectedIds: ID[],
) => {
  let unlikely = 0;
  for (const selectedId of selectedIds) {
    const state = getInconsistency(inconsistencies, id, selectedId);
    if (state === true) return undefined;
    if (state === false) unlikely++;
  }
  return unlikely;
};

const shuffle = <T>(array: T[]) =>
  array
    .map((value) => ({ value, rank: Math.random() }))
    .sort((a, b) => a.rank - b.rank)
    .map(({ value }) => value);

export const generateNarrative = (
  scenario: Scenario,
  locked: Record<ID, ID[]> = {},
) => {
  const { categories, components, inconsistencies } = scenario;

  const orderedComponents = getScenarioComponents(categories, components).sort(
    (a, b) =>
      (b.values || []).reduce(
        (sum, value) => sum + countConstraints(inconsistencies, value.id),
        0,
      ) -
      (a.values || []).reduce(
        (sum, value) => sum + countConstraints(inconsistencies, value.id),
        0,
      ),
  );
  const chosen = Object.fromEntries(
    Object.entries(locked).map(([id, valueIds]) => [id, valueIds || []]),
  ) as Record<ID, ID[]>;
  const lockedValueIds = getSelectedValueIds(chosen);
  let lockedUnlikelyCount = 0;

  for (let i = 0; i < lockedValueIds.length; i++) {
    const score = getPairScore(
      inconsistencies,
      lockedValueIds[i],
      lockedValueIds.slice(i + 1),
    );
    if (typeof score === 'undefined') {
      return { error: true, diagnostic: diagnoseGeneration(scenario) } as const;
    }
    lockedUnlikelyCount += score;
  }

  let best:
    | {
        chosen: Record<ID, ID[]>;
        unlikelyCount: number;
      }
    | undefined;

  const search = (
    componentIndex: number,
    current: Record<ID, ID[]>,
    selectedValueIds: ID[],
    unlikelyCount: number,
  ) => {
    if (best && unlikelyCount >= best.unlikelyCount) return;
    if (componentIndex >= orderedComponents.length) {
      best = { chosen: current, unlikelyCount };
      return;
    }

    const component = orderedComponents[componentIndex];
    if (Object.prototype.hasOwnProperty.call(current, component.id)) {
      search(componentIndex + 1, current, selectedValueIds, unlikelyCount);
      return;
    }

    const candidates = shuffle(component.values || [])
      .map(({ id }) => ({
        id,
        score: getPairScore(inconsistencies, id, selectedValueIds),
      }))
      .filter(
        (candidate): candidate is { id: ID; score: number } =>
          typeof candidate.score !== 'undefined',
      )
      .sort((a, b) => a.score - b.score);

    for (const candidate of candidates) {
      search(
        componentIndex + 1,
        { ...current, [component.id]: [candidate.id] },
        selectedValueIds.concat(candidate.id),
        unlikelyCount + candidate.score,
      );
    }
  };

  search(0, chosen, lockedValueIds, lockedUnlikelyCount);

  if (best) {
    const narrative = {
      id: uniqueId(),
      components: best.chosen,
      included: false,
    } as Narrative;
    return narrative;
  }

  // Return diagnostic info so caller can report why generation failed
  return { error: true, diagnostic: diagnoseGeneration(scenario) } as const;
};

export const scrollToSection = (id: string, e?: MouseEvent): void => {
  e && e.preventDefault();
  const element = document.getElementById(id);

  if (element) {
    element.scrollIntoView({ behavior: 'smooth' });
  } else {
    console.log(`Element with id ${id} not found.`);
  }
};

export const scrollToTop = (): void => {
  window.scrollTo({
    top: 0,
    behavior: 'smooth',
  });
};

export const validateNarrative = (
  n: Narrative,
  components: ScenarioComponent[],
) => {
  const { components: narrativeComps, ...attrs } = n;
  const newNarrative = { components: {}, ...attrs } as Narrative;
  components
    .filter((c) => narrativeComps.hasOwnProperty(c.id))
    .forEach((c) => {
      newNarrative.components[c.id] = narrativeComps[c.id].filter((id) =>
        c.values?.find((v) => v.id === id),
      );
    });
  return newNarrative;
};

export const narrativesToOptions = (narratives: Narrative[]) =>
  narratives
    .map((n) => ({
      ...n,
      group: n.included ? t('GROUP', 'SELECTED') : t('GROUP', 'UNSELECTED'),
    }))
    .sort((a, b) =>
      a.included && b.included
        ? (a.label || '').localeCompare(b.label)
        : a.included
          ? -1
          : 1,
    );

